package org.diy.liferecorder;

import android.app.*;
import android.content.*;
import android.os.*;
import android.text.*;
import android.text.style.BackgroundColorSpan;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.text.SimpleDateFormat;
import java.util.concurrent.*;

/** Local search stays useful without an API; asking is an explicit selection of sources. */
public final class SearchActivity extends AppScreen {
    private final Handler updates=new Handler();private final ExecutorService searchWorker=Executors.newSingleThreadExecutor();private volatile int generation;private boolean active;
    private EditText query,question;private LinearLayout results,answers,rangeControls;private TextView searchStatus,selectionLabel;private Button ask;private long from=0,to=Long.MAX_VALUE;private String range="全部时间",session=UUID.randomUUID().toString(),lastJobs="";private JSONObject previousTurn;private final LinkedHashSet<String> selected=new LinkedHashSet<>();private final Map<String,CheckBox> choices=new HashMap<>();
    private final Runnable answerPoll=new Runnable(){public void run(){if(!active)return;renderAnswers();updates.postDelayed(this,1800);}};
    public void onCreate(Bundle state){super.onCreate(state);if(state!=null){from=state.getLong("from",0);to=state.getLong("to",Long.MAX_VALUE);range=state.getString("range","全部时间");session=state.getString("session",session);ArrayList<String> restored=state.getStringArrayList("selected");if(restored!=null)selected.addAll(restored);try{if(state.containsKey("previous_turn"))previousTurn=new JSONObject(state.getString("previous_turn"));}catch(Exception ignored){}}frame("搜索记录");button(body,"‹ 返回语音回看",this::finish);body.addView(title("想找回哪一刻？",26));body.addView(text("输入关键词或一句描述，在本机查找原文与已保存记忆。",14,MUTED));gap(body,14);
        LinearLayout search=card(body);query=field(search,"关键词或描述",state==null?getIntent().getStringExtra("query")==null?"":getIntent().getStringExtra("query"):state.getString("query",""),android.text.InputType.TYPE_CLASS_TEXT);query.setSingleLine(true);query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);query.setHint("例如：方案最后确定了什么");query.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH){find();return true;}return false;});rangeControls=row();search.addView(rangeControls);rangeControls();primary(search,"查找记录",this::find);search.addView(text("在本机查找关键词与相关表达，无需联网。",11,MUTED));searchStatus=text("还记得人物、项目或一句原话，都可以从这里开始。",13,MUTED);body.addView(searchStatus);results=column();body.addView(results);
        LinearLayout askCard=card(body);askCard.addView(title("有依据地问一问",19));askCard.addView(text("勾选搜索结果后，只发送你选中的来源。每条结论保留原文引用与回听入口。",13,MUTED));selectionLabel=text("尚未选择来源",12,SAGE);askCard.addView(selectionLabel);question=field(askCard,"关于这些记录，你想知道…",state==null?"":state.getString("question",""),android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);ask=primary(askCard,"依据所选记录提问",this::ask);updateSelection();
        if(!configured()){askCard.addView(text("尚未配置 AI 服务。搜索和回听可以直接使用。",12,MUTED));button(askCard,"配置 AI 服务",()->startActivity(new Intent(this,MainActivity.class).putExtra("page","settings").putExtra("setting","llm")));}
        answers=column();body.addView(answers);if(!query.getText().toString().trim().isEmpty())find(state!=null);
    }
    private boolean configured(){SecureSettings s=new SecureSettings(this);return !s.endpoint("llm").trim().isEmpty()&&!s.model("llm").trim().isEmpty();}
    private void rangeControls(){rangeControls.removeAllViews();Button b=button(rangeControls,range+"  ⌄",()->new LocalDialog(this).setTitle("搜索时间范围").setItems(new String[]{"全部时间","最近 7 天","最近 30 天","自定义日期"},(d,which)->{if(which==3){pickRange();return;}Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);from=0;to=Long.MAX_VALUE;range="全部时间";if(which>0){c.add(Calendar.DAY_OF_MONTH,which==1?-6:-29);from=c.getTimeInMillis();range=which==1?"最近 7 天":"最近 30 天";}rangeControls();if(!query.getText().toString().trim().isEmpty())find();}).show());b.setMaxLines(2);}
    private void pickRange(){Calendar start=Calendar.getInstance();if(from>0)start.setTimeInMillis(from);DatePickerDialog first=new PebbleDatePickerDialog(this,(v,y,m,d)->{Calendar a=Calendar.getInstance();a.set(y,m,d,0,0,0);a.set(Calendar.MILLISECOND,0);Calendar end=Calendar.getInstance();DatePickerDialog last=new PebbleDatePickerDialog(this,(w,yy,mm,dd)->{Calendar b=Calendar.getInstance();b.set(yy,mm,dd,0,0,0);b.set(Calendar.MILLISECOND,0);b.add(Calendar.DAY_OF_MONTH,1);if(b.getTimeInMillis()<=a.getTimeInMillis()){notice.setText("结束日期不能早于开始日期");return;}from=a.getTimeInMillis();to=b.getTimeInMillis();range=date(from,"M/d")+" – "+date(to-1,"M/d");rangeControls();if(!query.getText().toString().trim().isEmpty())find();},end.get(Calendar.YEAR),end.get(Calendar.MONTH),end.get(Calendar.DAY_OF_MONTH));last.setTitle("结束日期（含当天）");last.show();},start.get(Calendar.YEAR),start.get(Calendar.MONTH),start.get(Calendar.DAY_OF_MONTH));first.setTitle("开始日期");first.show();}
    private void find(){find(false);}
    private void find(boolean keepSelection){String value=query.getText().toString().trim();if(value.isEmpty()){searchStatus.setText("请输入人物、项目或想找的内容。");return;}if(RecordSearch.terms(value).isEmpty()){searchStatus.setText("请补充至少两个字的线索，例如人物名字或项目名称。");return;}final int version=++generation;final long start=from,end=to;if(!keepSelection){selected.clear();previousTurn=null;}updateSelection();results.removeAllViews();searchStatus.setText("正在检查本地索引…");searchWorker.execute(()->{if(version!=generation)return;try(RecordStore db=new RecordStore(getApplicationContext());RecordSearch index=new RecordSearch(getApplicationContext())){index.sync(db,(done,total)->runOnUiThread(()->{if(version==generation&&!isDestroyed())searchStatus.setText("正在更新本地索引 · "+(total==0?100:done*100/total)+"%");}));if(version!=generation)return;RecordSearch.Result found=index.find(value,start,end);runOnUiThread(()->{if(version==generation&&!isDestroyed())showResults(found);});}catch(Exception error){runOnUiThread(()->{if(version==generation&&!isDestroyed())searchStatus.setText("搜索未完成，请重试。原录音与文字仍然保留。");});}});}
    private void showResults(RecordSearch.Result result){results.removeAllViews();choices.clear();searchStatus.setText(result.total+" 条匹配 · "+range+(result.total>result.hits.size()?" · 展示相关度最高的 "+result.hits.size()+" 条":""));if(result.total==0){LinearLayout empty=card(results);empty.addView(title("换一个线索试试",18));empty.addView(text("可以缩短描述，换成人物、项目或一句原话；也可以放宽时间范围。还未转写的录音只能通过标题查找。",14,MUTED));if(from>0)button(empty,"改为全部时间",()->{from=0;to=Long.MAX_VALUE;range="全部时间";rangeControls();find();});return;}
        String day="";LinkedHashMap<String,List<RecordSearch.Hit>> groups=new LinkedHashMap<>();for(RecordSearch.Hit hit:result.hits)groups.computeIfAbsent(hit.source,k->new ArrayList<>()).add(hit);
        for(List<RecordSearch.Hit> hits:groups.values()){RecordSearch.Hit first=hits.get(0);String next=date(first.created,"yyyy年M月d日");if(!next.equals(day)){results.addView(title(next,17));gap(results,8);day=next;}LinearLayout c=card(results);LinearLayout header=row();CheckBox choice=new CheckBox(this);choice.setButtonTintList(android.content.res.ColorStateList.valueOf(SAGE));choice.setMinWidth(dp(48));choice.setMinHeight(dp(48));choice.setContentDescription("选择来源："+first.title);choice.setChecked(selected.contains(first.source));choices.put(first.source,choice);header.addView(choice);LinearLayout heading=column();heading.addView(rawTitle(first.title,16));heading.addView(text(date(first.created,"HH:mm")+" · "+hits.size()+" 处展示匹配",11,MUTED));header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));c.addView(header);choice.setOnCheckedChangeListener((v,on)->{if(on)selected.add(first.source);else selected.remove(first.source);previousTurn=null;updateSelection();});
            int shown=0;for(RecordSearch.Hit hit:hits){if(shown++>=3)break;LinearLayout snippet=inset(c,TINT);snippet.addView(text(hit.kind.equals("memory")?"已保存记忆":hit.kind.equals("title")?"标题匹配":hit.timed?"原文 · "+clock(hit.start):"原文 · 尚无时间码",11,SAGE));TextView excerpt=rawText("",14,INK);excerpt.setText(highlight(RecordSearch.excerpt(hit.text,result.terms),result.terms));snippet.addView(excerpt);button(snippet,hit.timed?"回听这一句 · "+clock(hit.start):"查看来源",()->openHit(hit));}if(hits.size()>3)c.addView(text("另有 "+(hits.size()-3)+" 处匹配，可在来源中继续查看。",11,MUTED));}
    }
    private CharSequence highlight(String value,List<String> terms){SpannableString out=new SpannableString(value);String lower=value.toLowerCase(Locale.ROOT);for(String term:terms){int at=0;while((at=lower.indexOf(term,at))>=0){out.setSpan(new BackgroundColorSpan(0xffead5c9),at,at+term.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);at+=term.length();}}return out;}
    private void openHit(RecordSearch.Hit hit){try{JSONObject a=store.audio(hit.source);if(a.optLong("transcript_revision")!=hit.revision){notice.setText("这段原文已更新，请重新搜索后定位。");return;}Intent i=new Intent(this,RecordActivity.class).putExtra("id",hit.source);if(hit.timed)i.putExtra("seek_ms",hit.start);startActivity(i);}catch(Exception e){notice.setText("来源已经移除，请重新搜索。");}}
    private void updateSelection(){if(selectionLabel!=null)selectionLabel.setText(selected.isEmpty()?"尚未选择来源":"已选择 "+selected.size()+" 段来源"+(previousTurn==null?"":" · 继续本次会话"));if(ask!=null)ask.setEnabled(!selected.isEmpty()&&configured());}
    private void ask(){String value=question.getText().toString().trim();if(value.isEmpty())value=query.getText().toString().trim();if(value.isEmpty()){notice.setText("先写下关于这些来源的问题。");return;}if(selected.isEmpty()){notice.setText("请先选择搜索结果，未找到来源不会发送请求。");return;}try{if(selected.size()>30){notice.setText("一次最多选择 30 段来源，请缩小范围。");return;}JSONArray ids=new JSONArray();int chars=0;for(String id:selected){JSONObject a=store.audio(id);ids.put(id);chars+=a.optString("transcript").length();}if(chars>55000){notice.setText("所选原文较长，请减少来源后提问。");return;}JSONObject input=new JSONObject().put("sources",ids).put("question",value).put("citation_request",true).put("conversation_id",session).put("provider",new ProviderClient(this).snapshot("llm"));if(previousTurn!=null)input.put("previous_turn",previousTurn);SourceAnswer.prepare(store,input);confirmJob("","answer",input,()->{lastJobs="";renderAnswers();notice.setText("问题已加入任务，可继续检索或等待结果。");});}catch(Exception e){notice.setText(e.getMessage()==null?"无法准备本次问答，请检查所选来源。":e.getMessage());}}
    private void renderAnswers(){if(answers==null)return;try{JSONArray jobs=store.rows("SELECT id,result,status,error,created FROM jobs WHERE type='answer' ORDER BY created DESC LIMIT 12");String signature=jobs.toString();if(signature.equals(lastJobs))return;lastJobs=signature;answers.removeAllViews();boolean titled=false;for(int i=0;i<jobs.length();i++){JSONObject job=jobs.getJSONObject(i),input=new JSONObject(store.rows("SELECT input FROM jobs WHERE id=?",job.getString("id")).getJSONObject(0).getString("input"));if(!input.optBoolean("citation_request"))continue;if(!titled){answers.addView(title("有来源的回答",20));gap(answers,10);titled=true;}LinearLayout c=card(answers);c.addView(rawTitle(input.optString("question"),16));c.addView(text(date(job.optLong("created"),"M/d HH:mm")+" · "+label(job.optString("status")),11,MUTED));if(!job.optString("status").equals("done")){c.addView(text(job.optString("error").isEmpty()?"正在依据所选原文整理，完成后会自动显示。":job.optString("error"),13,MUTED));continue;}JSONObject answer=new JSONObject(job.optString("result"));JSONArray claims=answer.getJSONArray("claims");for(int n=0;n<claims.length();n++){JSONObject claim=claims.getJSONObject(n);LinearLayout block=inset(c,PAPER);block.addView(text(claim.optString("kind").equals("inference")?"模型推测 · 待核对":"记录支持的结论",11,claim.optString("kind").equals("inference")?ACCENT:SAGE));block.addView(rawText(claim.optString("text"),14,INK));JSONArray refs=claim.getJSONArray("citations");for(int r=0;r<refs.length();r++){JSONObject ref=refs.getJSONObject(r);block.addView(rawText("“"+ref.optString("quote")+"”",12,MUTED));button(block,"▷ "+date(ref.optLong("source_created"),"M/d HH:mm")+" · "+clock(ref.optLong("start_ms"))+" 回听原声",()->openCitation(ref));}}
                if(!answer.optString("unanswered").isEmpty())c.addView(rawText(answer.optString("unanswered"),14,MUTED));button(c,"继续追问这些来源",()->{try{selected.clear();JSONArray ids=input.getJSONArray("sources");for(int n=0;n<ids.length();n++)selected.add(ids.getString(n));for(Map.Entry<String,CheckBox> choice:choices.entrySet())choice.getValue().setChecked(selected.contains(choice.getKey()));session=input.optString("conversation_id",session);previousTurn=new JSONObject().put("question",input.optString("question")).put("answer",answer);question.setText("");question.setHint("例如：那下一步需要做什么？");updateSelection();question.requestFocus();android.graphics.Rect rect=new android.graphics.Rect();question.getDrawingRect(rect);body.offsetDescendantRectToMyCoords(question,rect);scroll.smoothScrollTo(0,rect.top);notice.setText("追问仍限定在这次选择的 "+selected.size()+" 段来源。");}catch(Exception e){notice.setText("无法恢复本次来源。");}});
            }}catch(Exception ignored){}}
    private void openCitation(JSONObject ref){try{JSONObject a=store.audio(ref.getString("source_id"));if(a.optLong("transcript_revision")!=ref.optLong("source_revision")){new LocalDialog(this).setTitle("原文已修订").setMessage("这条回答保留了当时引用的原文。当前转写已更新，可打开来源核对。\n\n"+ref.optString("quote")).setPositiveButton("查看当前来源",(d,w)->openRecord(ref.optString("source_id"))).setNegativeButton("关闭",null).show();return;}if(!SourceAnswer.playable(a,new JSONObject().put("timed",true).put("start_ms",ref.optLong("start_ms")).put("end_ms",ref.optLong("end_ms")))){messageRaw("原声目前不可用","当时引用的原文仍保留：\n\n"+ref.optString("quote"));return;}startActivity(new Intent(this,RecordActivity.class).putExtra("id",ref.getString("source_id")).putExtra("seek_ms",ref.optLong("start_ms")));}catch(Exception e){messageRaw("来源已移除","当时引用的原文：\n\n"+ref.optString("quote"));}}
    private static String clock(long ms){return ms/60000+":"+String.format(Locale.ROOT,"%02d",ms/1000%60);}
    private static String date(long time,String pattern){return new SimpleDateFormat(pattern,Locale.CHINA).format(new Date(time));}
    protected void onResume(){super.onResume();active=true;lastJobs="";updates.removeCallbacks(answerPoll);updates.post(answerPoll);updateSelection();}
    protected void onPause(){active=false;updates.removeCallbacks(answerPoll);super.onPause();}
    public void onSaveInstanceState(Bundle out){out.putLong("from",from);out.putLong("to",to);out.putString("range",range);out.putString("session",session);out.putString("query",query.getText().toString());out.putString("question",question.getText().toString());out.putStringArrayList("selected",new ArrayList<>(selected));if(previousTurn!=null)out.putString("previous_turn",previousTurn.toString());super.onSaveInstanceState(out);}
    public void onDestroy(){generation++;updates.removeCallbacksAndMessages(null);searchWorker.shutdownNow();super.onDestroy();}
}
